#' Categorical Variable Tree (Python Core)
#'
#' 
#' @param data .
#' @param vars .
#' @param showTree .
#' @param showPlot .
#' @param showPaths .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$nodes} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$explorer} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$leafPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$nodes$asDF}
#'
#' \code{as.data.frame(results$nodes)}
#'
#' @export
pyvartree <- function(
    data,
    vars = NULL,
    showTree = TRUE,
    showPlot = FALSE,
    showPaths = FALSE,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pyvartree requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL))

    for (v in vars) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- pyvartreeOptions$new(
        vars = vars,
        showTree = showTree,
        showPlot = showPlot,
        showPaths = showPaths,
        showConsole = showConsole)

    analysis <- pyvartreeClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

